            "padding-top":
              "max(var(--ornament-clearance, 0px), var(--doc-pad-y, 2.5rem))",
            "padding-bottom":
              "max(var(--ornament-clearance, 0px), var(--doc-pad-bottom, 4rem))",
          }}
        >
