  fill: var(--color-paper);
  stroke: color-mix(in srgb, var(--color-ink) 55%, transparent);
  stroke-width: 1;
}
.flow-ribbon__band {
  transition:
    transform 1.6s ease,
    opacity 1.2s ease;
}
.flow-ribbon__black {
  fill: var(--color-ink);
}
.flow-ribbon__red {
  fill: var(--color-vermilion);
}
.flow-ribbon__slack {
  fill: none;
  stroke: var(--color-ink);
  stroke-width: 2.4;
  opacity: 0;
  transition: opacity 1.2s ease;
}
