{"index":0,"status":"fulfilled","value":{"chunk_id":"db6d45","wall_time_seconds":0.000016943,"exit_code":0,"original_token_count":3796,"output":"/**
 * Pure positioning math for the persona-note popover. Lives in its
 * own module so the editor can import it (no Qwik dependency) and
 * so the placement rules — "prefer below the sentence, flip fully
 * above when the bottom would clip (never overlap the marked text),
 * and clamp height to the available room on whichever side wins" —
 * are unit-testable without a Tiptap editor.
 */

export const POPOVER_CARD_WIDTH = 340;
export const POPOVER_CARD_MARGIN = 8;
export const MARGIN_CARD_GAP = 12;
/**
 * The popover's *content*-driven height. The CSS rule that the
 * card inflates to lives inside the JSX; this is the "ideal" we ask
 * for when there is room below the sentence. The renderer clamps the
 * final `maxH` to the available space on the chosen side.
 */
export const POPOVER_CARD_IDEAL_HEIGHT = 520;

export type PopoverPlacement = "below" | "above";

export interface PopoverGeometry {
  /** The card's top-left x in viewport coordinates. */
  x: number;
  /** Top offset in px (or null when the card is bottom-anchored above). */
  top: number | null;
  /** Bottom offset in px (or null when the card is top-anchored below). */
  bottom: number | null;
  /** Final max-height in px, clamped to the available space on the chosen side. */
  maxH: number;
  /** Which side of the anchor the card sits on. */
  placement: PopoverPlacement;
}

export interface AnchorRect {
  left: number;
  top: number;
  bottom: number;
}

export interface PopoverView {
  /** Viewport width. */
  vw: number;
  /** Viewport height. */
  vh: number;
  /** The marked span's bounding rect. */
  rect: AnchorRect;
  /** Ideal card height; defaults to POPOVER_CARD_IDEAL_HEIGHT. */
  idealH?: number;
}

export interface MarginCardView extends PopoverView {
  /** The visible manuscript page whose outside margins the card should use. */
  page: { left: number; right: number };
}

export interface FallbackCardView extends MarginCardView {
  /** Pinned cards and unsent drafts survive scrolling away. */
  keepOpen: boolean;
  /** The manuscript scroller's visible vertical interval, clipped to the window. */
  viewport?: { top: number; bottom: number };
}

/** Follow a fallback passage, closing idle cards or keeping protected ones on screen. */
export function computeFallbackCardGeometry(view: FallbackCardView): PopoverGeometry | null {
  const margin = POPOVER_CARD_MARGIN;
  const viewportTop = Math.max(0, view.viewport?.top ?? 0);
  const viewportBottom = Math.min(view.vh, view.viewport?.bottom ?? view.vh);
  const outside = view.rect.bottom <= viewportTop || view.rect.top >= viewportBottom;
  if (outside && !view.keepOpen) return null;
  const clamp = (value: number, low: number, high: number) =>
    Math.max(low, Math.min(value, Math.max(low, high)));
  const edge = view.rect.bottom <= viewportTop
    ? viewportTop + margin : viewportBottom - margin;
  const geometry = computeMarginCardGeometry({
    ...view,
    rect: outside ? { left: view.rect.left, top: edge, bottom: edge } : view.rect,
  });
  const maxH = Math.min(geometry.maxH, Math.max(0, viewportBottom - viewportTop - margin * 2));
  return {
    ...geometry,
    maxH,
    top: geometry.top === null ? null
      : clamp(geometry.top, viewportTop + margin, viewportBottom - maxH - margin),
    bottom: geometry.bottom === null ? null
      : clamp(geometry.bottom, view.vh - viewportBottom + margin, view.vh - viewportTop - maxH - margin),
  };
}

/**
 * Place an editorial conversation beside the manuscript, Google-Docs style.
 * The right margin is the stable default; the left margin is used when it is
 * the only side with room. When neither margin can hold it, the card has to
 * sit over the page, so it tucks under (or over) the passage rather than on
 * it: the words being discussed stay readable. CSS turns that card into a
 * bottom sheet on phones.
 */
export function computeMarginCardGeometry(
  view: MarginCardView,
): PopoverGeometry {
  const margin = MARGIN_CARD_GAP;
  const cardWidth = POPOVER_CARD_WIDTH;
  const idealH = view.idealH ?? POPOVER_CARD_IDEAL_HEIGHT;
  const rightX = view.page.right + margin;
  const leftX = view.page.left - cardWidth - margin;
  const rightFits = rightX + cardWidth <= view.vw - margin;
  const leftFits = leftX >= margin;

  let x: number;
  if (rightFits) x = rightX;
  else if (leftFits) x = leftX;
  else {
    const roomRight = view.vw - view.page.right;
    const roomLeft = view.page.left;
    x = roomRight >= roomLeft ? rightX : leftX;
    x = Math.max(margin, Math.min(x, view.vw - cardWidth - margin));
    return { ...computePopoverGeometry({ ...view, idealH }), x };
  }

  const maxH = Math.max(0, Math.min(idealH, view.vh - margin * 2));
  const top = Math.max(
    margin,
    Math.min(view.rect.top, view.vh - maxH - margin),
  );

  return { x, top, bottom: null, maxH, placement: "below" };
}

/**
 * Decide where the popover should sit relative to the marked passage.
 *
 * Rules:
 *  1. Prefer just below the sentence (`rect.bottom + margin`).
 *  2. If the ideal card would clip the viewport bottom and there is
 *     strictly *more* room above than below, flip above. The flipped
 *     card is bottom-anchored so it grows upward from `rect.top - margin` —
 *     this matters because the card's final height is content-dependent,
 *     so a top-anchored flip would jitter as content streams in.
 *  3. Whichever side wins, clamp `maxH` to the available space so the
 *     card never overlaps the anchor.
 */
export function computePopoverGeometry(view: PopoverView): PopoverGeometry {
  const margin = POPOVER_CARD_MARGIN;
  const idealH = view.idealH ?? POPOVER_CARD_IDEAL_HEIGHT;

  const x = Math.max(
    margin,
    Math.min(view.rect.left, view.vw - POPOVER_CARD_WIDTH - margin),
  );

  const belowTop = view.rect.bottom + margin;
  const aboveBottomCoord = view.rect.top - margin;

  const spaceBelow = Math.max(0, view.vh - margin - belowTop);
  const spaceAbove = Math.max(0, aboveBottomCoord - margin);

  // Default: below. Only flip above if below can't fit AND above is strictly
  // roomier. Equal falls through to below — keeps behavior stable when the
  // anchor is roughly mid-viewport.
  const flipAbove = spaceBelow < idealH && spaceAbove > spaceBelow;

  if (flipAbove) {
    const maxH = Math.max(0, Math.min(idealH, spaceAbove));
    // bottom offset relative to viewport: vh - rect.top + margin
    return {
      x,
      top: null,
      bottom: Math.max(0, view.vh - view.rect.top + margin),
      maxH,
      placement: "above",
    };
  }

  const maxH = Math.max(0, Math.min(idealH, spaceBelow));
  return {
    x,
    top: belowTop,
    bottom: null,
    maxH,
    placement: "below",
  };
}
/**
 * One surface per note.
 *
 * When the flow surface has its room rail on screen, a writer comment or a
 * persona note already has a card level with its passage. Opening its
 * conversation must not raise a second, differently placed card: the
 * conversation unfolds in the card's own slot, and the card steps aside
 * while it is open. The editor owns the conversations (reply, resolve,
 * persona threads); the flow surface owns the margin. This module is the
 * handshake between the two, so neither has to import the other.
 */

/** Where an unfolded conversation sits, in viewport pixels (it is fixed). */
export interface MarginSlot {
  left: number;
  top: number;
  width: number;
  maxH: number;
}

export interface MarginSurface {
  /** The room rail is on screen and carrying notes. */
  active(): boolean;
  /**
   * Place the item's card if it is waiting (or was set aside), then say where
   * its thread opens. `anchorTop` is the passage's viewport top, used when the
   * item has no card at all — a resolved comment, say.
   */
  reveal(itemId: string, anchorTop: number): Promise<MarginSlot | null>;
  /** The item whose conversation is open over its card, or null. */
  setOpen(itemId: string | null): void;
}

/** Fired by the surface whenever the open card's slot moves (scroll, reflow). */
export const MARGIN_SLOT_EVENT = "twyne:margin-slot";
export interface MarginSlotDetail {
  itemId: string;
  slot: MarginSlot;
}

/** Fired by the surface when the writer opens a card's conversation from the card. */
export const OPEN_MARGIN_THREAD_EVENT = "twyne:open-margin-thread";
export interface OpenMarginThreadDetail {
  kind: "comment" | "note";
  id: string;
}

let current: MarginSurface | null = null;

export function registerMarginSurface(surface: MarginSurface): () => void {
  current = surface;
  return () => {
    if (current === surface) current = null;
  };
}

/** The live surface, but only while it is actually taking notes. */
export function marginSurface(): MarginSurface | null {
  return current?.active() ? current : null;
}

/** Tell the surface which card's conversation is open (null: none). */
export function setMarginThread(itemId: string | null): void {
  current?.setOpen(itemId);
}

/** Popover placement for a slot: the shape the editor's cards already take. */
export function slotPlacement(slot: MarginSlot) {
  return {
    x: slot.left,
    top: slot.top,
    bottom: null,
    maxH: slot.maxH,
    width: slot.width,
  };
}

export const commentItemId = (id: string) => `comment:${id}`;
export const noteItemId = (id: string) => `note:${id}`;
export const suggestionItemId = (id: string) => `suggestion:${id}`;
import { chromium, expect } from "@playwright/test";
const BASE = "http://127.0.0.1:5180";
const width = Number(process.env.W || 1600);
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width, height: 1000 } });
const errs = [];
page.on("pageerror", (e) => errs.push("pageerror: " + e.message));
