  mode: FlowMode,
  runMs: number,
  pauseMs: number,
  activeRatio: number,
  deleteRatio: number,
  wpm: number,
  recentChurn: number,
  reason: string,
): FlowReading {
  return {
    mode,
    runMs,
    pauseMs,
    activeRatio,
    deleteRatio,
    wpm,
    recentChurn,
    reason,
