 78	const push = (list: number[], value: number) =>
 79	  [...list, Math.round(value)].slice(-MAX_SAMPLES);
 80	
 81	export function recordPause(p: FlowProfile, ms: number, now: number): FlowProfile {
 82	  // Sub-second gaps are typing, and long ones are someone making tea.
 83	  if (ms < 1_500 || ms > 10 * 60_000) return p;
 84	  return { ...p, pauses: push(p.pauses, ms), updatedAt: now };
 85	}
 86	
 87	export function recordRun(
 88	  p: FlowProfile,
 89	  ms: number,
 90	  now: number,
 91	  hour = new Date(now).getHours(),
 92	): FlowProfile {
 93	  if (ms < 5_000) return p;
 94	  const hours = [...p.hours];
 95	  hours[hour] = (hours[hour] ?? 0) + ms / 60_000;
 96	  return { ...p, runs: push(p.runs, ms), hours, updatedAt: now };
 97	}
 98	
