108	  p: FlowProfile,
109	  kind: string,
110	  outcome: ItemOutcome,
111	  now: number,
112	): FlowProfile {
113	  const stats = p.kinds[kind] ?? { shown: 0, engaged: 0, dismissed: 0 };
114	  return {
115	    ...p,
116	    kinds: { ...p.kinds, [kind]: { ...stats, [outcome]: stats[outcome] + 1 } },
117	    updatedAt: now,
118	  };
119	}
120	
121	export function quantile(values: readonly number[], q: number): number | null {
122	  if (!values.length) return null;
123	  const sorted = [...values].sort((a, b) => a - b);
124	  const index = Math.min(sorted.length - 1, Math.max(0, (sorted.length - 1) * q));
125	  const lo = Math.floor(index);
126	  const hi = Math.ceil(index);
127	  return sorted[lo] + (sorted[hi] - sorted[lo]) * (index - lo);
128	}
129	
130	const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
131	
132	/**
133	 * Fit the detector to the writer. Needs a dozen pauses before it trusts
134	 * them; until then the defaults hold.
135	 */
136	export function thresholdsFor(p: FlowProfile): FlowThresholds {
137	  const t = { ...DEFAULT_THRESHOLDS };
138	  if (p.pauses.length >= 12) {
139	    const typical = quantile(p.pauses, 0.75)!;
140	    const long = quantile(p.pauses, 0.9)!;
141	    t.stuckPauseMs = clamp(typical * 2, 12_000, 60_000);
142	    t.exitPauseMs = clamp(long * 1.5, 15_000, 45_000);
143	  }
144	  if (p.flowEntries.length >= 5) {
145	    t.flowMs = clamp(quantile(p.flowEntries, 0.5)!, 60_000, 240_000);
146	    t.settleMs = Math.round(t.flowMs / 3);
147	  }
148	  return t;
149	}
150	
151	/** 0.2..1.8 — how much this writer uses help of this kind. Neutral at 1. */
152	export function kindWeight(p: FlowProfile, kind: string): number {
153	  const s = p.kinds[kind];
154	  if (!s) return 1;
155	  const rate = (s.engaged + 1) / (s.engaged + s.dismissed + 2);
156	  return clamp(rate * 2, 0.2, 1.8);
157	}
